fn roster_message(
    room_id: u64,
    members: &HashMap<u64, NativeActorMember>,
    session: &NativeRoomSession,
) -> ServerMessage {
    let mut seats: Vec<SeatPresence> = members
        .values()
        .filter(|m| m.role == ClientRole::Player)
        .map(|m| SeatPresence {
            seat: m.seat,
            player_id: m.player_id.raw(),
            display_name: m.display_name.clone(),
            connected: m.outbound.is_some(),
            managed: session.timeout_state().managed_seats.contains(&m.seat),
        })
        .collect();
    seats.sort_by_key(|s| s.seat);
    ServerMessage::RoomRoster {
        room_id,
        seats,
        started: true,
        finished: session.engine().outcome().is_some(),
        choice_timeout_secs: Some(session.timeout_state().choice_timeout_secs),
    }
}

async fn broadcast_roster_native(
    room_id: u64,
    members: &mut HashMap<u64, NativeActorMember>,
    session: &NativeRoomSession,
) {
    let msg = roster_message(room_id, members, session);
    let mut stalled = Vec::new();
    for m in members.values() {
        if let Some(out) = &m.outbound {
            if out.try_send(&msg) == SendStatus::Full {
                stalled.push(m.connection_id);
            }
        }
    }
    if stalled.is_empty() {
        return;
    }
    drop_stalled(members, stalled);
    // 已断开的连接不应再出现在名册的 connected=true 中；仅对剩余连接重发。
    let msg = roster_message(room_id, members, session);
    for m in members.values() {
        if let Some(out) = &m.outbound {
            let _ = out.try_send(&msg);
        }
    }

/// 有界非阻塞发送：队列满时标记慢连接并返回 `Full`，绝不等待。
pub fn try_send(&self, msg: &ServerMessage) -> SendStatus {
    let Ok(text) = encode_s2c(msg) else {
        return SendStatus::Closed;
    };
    match self.tx.try_send(text) {
        Ok(()) => SendStatus::Queued,
        Err(mpsc::error::TrySendError::Full(_)) => {
            self.mark_slow();
            SendStatus::Full
        }
        Err(mpsc::error::TrySendError::Closed(_)) => SendStatus::Closed,
    }
}

/// 入座（满座或座位被占时返回错误；同令牌为重连）。
pub fn join(
    &mut self,
    connection_id: u64,
    preferred_seat: Option<u8>,
    reconnect_token: Option<String>,
) -> Result<NativeJoinReply, String> {
    // 重连：换绑连接、保留座位与令牌
    if let Some(token) = reconnect_token {
        if let Some(old) = self.by_token.get(&token).copied() {
            if old != connection_id && self.members.contains_key(&connection_id) {
                return Err("connection already in room".into());
            }
            if let Some(mut m) = self.members.remove(&old) {
                m.connection_id = connection_id;
                if m.role == ClientRole::Player {
                    self.timeout.managed_seats.retain(|s| *s != m.seat);
                }
                let reply = self.reply_for(&m);
                self.by_token.insert(token, connection_id);
                self.members.insert(connection_id, m);
                return Ok(reply);
            }
        }
        return Err("invalid reconnect token".into());
    }
    if self.members.contains_key(&connection_id) {
        return Err("connection already in room".into());
    }
    let seat = preferred_seat
        .filter(|s| *s < self.max_seats && !self.seat_taken(*s))
        .or_else(|| (0..self.max_seats).find(|s| !self.seat_taken(*s)))
        .ok_or_else(|| "room full".to_string())?;
    let token = uuid::Uuid::new_v4().to_string();
    self.next_token += 1;
    let member = NativeMember {
        connection_id,
        player_id: PlayerId::new(seat as u32 + 1),
        seat,
        role: ClientRole::Player,
        reconnect_token: token.clone(),
    };
    self.by_token.insert(token, connection_id);
    let reply = self.reply_for(&member);
    self.members.insert(connection_id, member);
    Ok(reply)
}

